}

const AimingReticle: React.FC<AimingReticleProps> = ({
  variant = 'bow',
  size = 64,
  className,
  style,
}) => {
  const cls = classNames(styles.reticle, styles[variant], className)

  return (
    <div className={cls} style={{ width: size, height: size, ...style }}>
      <svg aria-hidden="true"
