import React, { useEffect, useId, useRef } from 'react'
import { createPortal } from 'react-dom'
import classNames from 'classnames'
import styles from './modal.module.less'

export interface ModalProps {
  /** demo */
  open: boolean
  /** demo */
  title?: React.ReactNode
  /** demo */
  width?: number | string
  /** demo */
  maskClosable?: boolean
  /** demo */
  footer?: React.ReactNode | null
  /** demo */
  onClose?: () => void
  /** demo */
  onOk?: () => void
  children?: React.ReactNode
  className?: string
}

/** demo (demo focus trap)  */
const FOCUSABLE = [
  'a[href]', 'button:not([disabled])', 'textarea:not([disabled])',
  'input:not([disabled])', 'select:not([disabled])', '[tabindex]:not([tabindex="-1"])',
].join(',')

const Modal: React.FC<ModalProps> = ({
  open,
  title,
  width = 480,
  maskClosable = true,
  footer,
  onClose,
  onOk,
  children,
  className,
}) => {
  const titleId = useId()
  const dialogRef = useRef<HTMLDivElement>(null)
  // demo, demo
  const prevFocusRef = useRef<HTMLElement | null>(null)

  // demo body demo: demo, demo (demo, demo) 
  useEffect(() => {
    if (!open) return
    const prevOverflow = document.body.style.overflow
    document.body.style.overflow = 'hidden'
    return () => { document.body.style.overflow = prevOverflow }
  }, [open])

  // Escape demo
  useEffect(() => {
    if (!open || !onClose) return
    const onKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Escape') onClose()
    }
    document.addEventListener('keydown', onKeyDown)
    return () => document.removeEventListener('keydown', onKeyDown)
  }, [open, onClose])

  // demo: demo, demo
  useEffect(() => {
    if (!open) return
    prevFocusRef.current = document.activeElement as HTMLElement | null
    // demo, demo
    const dialog = dialogRef.current
    const first = dialog?.querySelector<HTMLElement>(FOCUSABLE)
    ;(first ?? dialog)?.focus()
    return () => { prevFocusRef.current?.focus?.() }
  }, [open])

  if (!open) return null

  // focus trap: demo Tab demo, demo Tab demo
  const handleTrapKeyDown = (e: React.KeyboardEvent) => {
    if (e.key !== 'Tab') return
    const dialog = dialogRef.current
    if (!dialog) return
    const items = Array.from(dialog.querySelectorAll<HTMLElement>(FOCUSABLE))
    if (items.length === 0) { e.preventDefault(); return }
    const firstItem = items[0]
    const lastItem = items[items.length - 1]
    const active = document.activeElement
    if (e.shiftKey && active === firstItem) {
      e.preventDefault(); lastItem.focus()
    } else if (!e.shiftKey && active === lastItem) {
      e.preventDefault(); firstItem.focus()
    }
  }

  const handleMaskClick = () => {
    if (maskClosable && onClose) onClose()
  }

  const defaultFooter = (
    <>
      <button className={styles.cancelBtn} onClick={onClose}>Cancel</button>
      <button className={styles.confirmBtn} onClick={onOk}>Confirm</button>
    </>
  )

  const modal = (
    <div className={styles.overlay} onClick={handleMaskClick} role="presentation">
      <div
        ref={dialogRef}
        className={classNames(styles.modal, className)}
        style={{ width }}
        onClick={(e) => e.stopPropagation()}
        onKeyDown={handleTrapKeyDown}
        role="dialog"
        aria-modal="true"
        aria-labelledby={title ? titleId : undefined}
        tabIndex={-1}
      >
        {title && (
          <div className={styles.header}>
            <h3 className={styles.title} id={titleId}>{title}</h3>
            <button className={styles.closeBtn} onClick={onClose} aria-label="Close">✕</button>
          </div>
        )}
        <div className={styles.body}>{children}</div>
        {footer !== null && (
          <div className={styles.footer}>
            {footer === undefined ? defaultFooter : footer}
          </div>
        )}
      </div>
    </div>
  )

  // Portal demo body, demo overflow/transform/demo. 
  // SSR demo: demo document demo (demo hydrate demo portal) . 
  if (typeof document === 'undefined') return modal
  return createPortal(modal, document.body)
}

